
#[cfg(test)]mod forest_tests {
    use super::*;
    const RAW:&[u8]=include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\驗證紀錄\current\native-E149-mass69-fire70-inspection\20261024-155206-240172\1819.definition.txt");
    fn catalog(raw:&[u8])->SpriteActionCatalog{SpriteActionCatalog::parse_for_inspection(&[b"11297 0 0\n".as_slice(),raw].concat(),super::super::sprite_actions::ActionLimits::default()).unwrap()}
    fn clip()->Clip{Clip::new(Arc::new(qualify(&catalog(RAW)).unwrap().remove(0).2)).unwrap()}
    fn origin()->WorldCell{WorldCell{x:100,y:100}}
    fn cue()->Cue{Cue{target_origin:None,attack:super::super::native_attack_many::Attack{action:18,caster:1,position:[100,100],heading:0,sequence:7,graphics:1819,targets:vec![]},caster_incarnation:1,action_sequence:99,targets:vec![(2,true,Some(3))]}}
    #[test]fn three_children_then_relocated_root_are_four_diagonal_radius_one_positions(){let c=Clock::new(origin(),&clip(),[0;4]).unwrap();assert_eq!(c.nodes.iter().map(|n|[n.position.x-100,n.position.y-100]).collect::<Vec<_>>(),vec![[1,1],[-1,-1],[-1,1],[1,-1]]);assert!(!c.nodes.iter().any(|n|n.position==origin()));}
    #[test]fn independent_callbacks_preserve_four_sound_entries_four_Hit_markers_and_terminal_dwell(){
        let mut c=Clock::new(origin(),&clip(),[0;4]).unwrap();let e=c.advance(0).unwrap();assert_eq!(e.len(),4);assert!(e.iter().all(|e|e.source==1&&e.callback==1&&e.event==FrameEvent::Sound(710)));assert!(c.advance(0).unwrap().is_empty());let mut hits=vec![];let mut at=0;while !c.finished(){at=c.nodes.iter().filter_map(|n|n.playback.next_callback_millis()).min().unwrap();for e in c.advance(at*1_000_000).unwrap(){if e.event==FrameEvent::Hit{hits.push((at,e.node,e.source));}}}assert_eq!(hits,vec![(873,0,7),(873,1,7),(873,2,7),(873,3,7)]);assert_eq!(at,2369);assert!(c.nodes.iter().all(|n|n.source==0));
    }
    #[test]fn node_births_keep_separate_cursors_and_late_dispatch_does_not_catch_up(){let mut c=Clock::new(origin(),&clip(),[0,0,0,1_000_000]).unwrap();c.advance(1_000_000).unwrap();c.advance(125_000_000).unwrap();assert_eq!((c.nodes[0].source,c.nodes[3].source),(2,1));let h=c.clone();c.advance(2_000_000_000).unwrap();assert_eq!((c.nodes[0].source,c.nodes[3].source),(3,2));let mut restored=h;restored.advance(2_000_000_000).unwrap();assert_eq!((restored.nodes[0].source,restored.nodes[3].source),(3,2));assert!(restored.advance(1_999_999_999).is_err());}
    #[test]fn definition_rejects_changed_sound_class_duration_hit_or_mix(){let text=String::from_utf8(RAW.to_vec()).unwrap();for(a,b)in[("[710","<710"),("109.effect(0 -1)","109.effect(1 -1)"),("104.attr(8)","104.attr(128)"),("0.6:4!","0.6:5!"),("0.13:6","0.13:5")]{assert!(text.contains(a));assert!(qualify(&catalog(text.replace(a,b).as_bytes())).is_err());}}
    #[test]fn source_retirement_keeps_admission_but_clears_graph_and_active_audio_keys(){let h=History{generation:Some(4),seen:BTreeSet::from([(1,99)]),active:vec![Cast{cue:cue(),clock:Clock::new(origin(),&clip(),[0;4]).unwrap(),finished:false}],started:1,omitted:0};let mut stage=Stage::default();stage.restore(h.clone(),true);assert_eq!(stage.history.active_sequences(),BTreeSet::from([99]));stage.restore(h,false);assert_eq!(stage.active_casts(),0);assert!(stage.history.seen.contains(&(1,99)));let mut stale=History{generation:Some(5),..Default::default()};stale.merge_admission(&stage.history);assert!(stale.seen.is_empty());assert!(Clock::new(WorldCell{x:i32::MAX,y:0},&clip(),[0;4]).is_err());}
    #[test]fn complete_group_preflights_projection_and_fragment_capacity_before_submission(){let frame=super::super::sprite::SpriteFrame{fragments:Some(super::super::sprite::SpriteFrameFragments{references:vec![],atlas:Arc::new(vec![])}),x_offset:0,y_offset:0,width:0,height:0,frame_type:0,unknown1:0,unknown2:0,rgba:vec![]};let view=ViewProjection{anchor_cell:origin(),anchor_pixel:super::super::world_map::PixelPoint{x:0,y:0}};let mut q=vec![];for _ in 0..509{q.push(super::super::native_world_effects::Effect{frame:&frame,position:origin(),mix:Mix::Screen});}assert!(submit_group(&mut Target::Fragments(&mut q),&vec![(&frame,origin());4],view).is_err());assert_eq!(q.len(),509);q.clear();assert!(submit_group(&mut Target::Fragments(&mut q),&[(&frame,origin()),(&frame,WorldCell{x:i32::MAX,y:i32::MIN})],view).is_err());assert!(q.is_empty());}
    #[test]fn failed_reprepare_retires_without_restarting_old_graph_or_audio(){let mut stage=Stage::default();stage.history=History{generation:Some(4),seen:BTreeSet::from([(1,99)]),active:vec![Cast{cue:cue(),clock:Clock::new(origin(),&clip(),[0;4]).unwrap(),finished:false}],started:1,omitted:0};stage.error=Some("cancelled preparation".into());let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();w.generation=4;stage.update(&w,std::iter::empty(),0,0);assert!(stage.history.active_sequences().is_empty());assert_eq!(stage.history.omitted,1);stage.update(&w,std::iter::empty(),125_000_000,0);assert_eq!(stage.history.omitted,1);}
    #[test]
    #[ignore="LITO_SHARED_RESOURCE_ROOT; original1819/710, four independent nodes and root-only targets; memory fragments only"]
    fn original_bank_draws_four_screen_nodes_and_preserves_same_source_history(){
        let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}let own=w.own_actor().unwrap().clone();let mut c=cue();c.attack.caster=own.id;c.caster_incarnation=own.incarnation;c.attack.position=[own.x,own.y];w.many_attacks.push(c.clone());w.learned_skills.insert(70);let event=EnteredEvent{actor:own.id,sequence:99,action:18,frame:1,event:"Hit".into(),sound:None,prepared_audio:None};let mut stage=Stage::default();stage.prepare(&root,&w,&cancel,&mut None);assert!(stage.error.is_none());stage.update(&w,[&event].into_iter(),0,0);let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};let mut q=vec![];let(row,audio)=stage.draw_to(&mut Target::Fragments(&mut q),view);assert_eq!(q.len(),4);assert!(q.iter().all(|f|matches!(f.mix,Mix::Screen)));assert_eq!(row["groups"][0]["nodes"][3]["position"],json!([own.x+1,own.y-1]));assert_eq!(audio.len(),4);assert!(audio.iter().all(|a|a.actor==0&&a.sound==Some(710)&&a.prepared_audio.is_some()));drop(q);let h=stage.history();w.actors.clear();w.many_attacks.clear();w.learned_skills.clear();let before=serde_json::to_value(&w).unwrap();let mut restored=Stage::default();restored.restore(h,true);restored.prepare(&root,&w,&cancel,&mut None);let deadlines=[125,250,375,541,707,873];for at in deadlines{restored.update(&w,std::iter::empty(),at*1_000_000,0);}assert_eq!(restored.diagnostics.len(),4);assert_eq!(restored.diagnostics.iter().filter(|d|d["root_target_list"]==true&&d["targets"].as_array().unwrap().len()==1).count(),1);assert_eq!(serde_json::to_value(&w).unwrap(),before);w.many_attacks.push(c);restored.update(&w,[&event].into_iter(),873_000_000,0);assert_eq!(restored.history.started,1);
    }
}
